ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	"status": 404,
	"code": "NOT_FOUND",
	"message": {
		"message": "Subscription not found for the given MSISDN."
	},
	"messageServer": "",
	"cause": [{
		"origin": app.name,
		"message": "org.mule.extension.http.api.request.validator.NotFoundException"
	}]
}

%dw 2.0
output application/json
---
{
	"status": 500,
	"code": "SUBSCRIPTION_QUERY",
	"message": {
	  "message": (vars.errorMessageOutput default "") ++ (if (!isEmpty(error.muleMessage.typedValue.message.message default "")) " JSC: " ++ error.muleMessage.typedValue.message.message else "")
	},
	"messageServer": "",
	"cause": [
	  {
	    "origin": app.name,
	    "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
	  }
	]
}
